; CYCLES_FORWARD_BRANCHES
; AERIA TWISTER  -- generated by twister/gen.py, do not edit.
; The Balloon Shop's whirlwind (MoreWeather.h, Twister): one event of 10 .. 20 s. The pitch climbs
; RISE semitones (x u^1.3) and falls back in the last 15 %, through two Hann-windowed taps half a
; window apart on a 2032-frame window, while the sound whirls from side to side, faster and
; faster (0.3 Hz .. 0.3 + SPIN), and swells up to x 1.3.
;
;  knob 0 AMT   the trigger: going from under 64 to 64 or more starts ONE event; the knob is not
;               looked at again until the event has ended, and must come back under 64 to arm the next
;  knob 1 RISE  semitones at the top, 0 .. 12 (7 = the plugin)
;  knob 2 SPIN  spin added at the top: 5 Hz x v/64 (64 = the plugin: 0.3 -> 5.3 Hz)
;  knob 3 TIME  0 = RND, 10 s x 2^r (r random 0..1: the plugin's 10 .. 20 s); else 2 s x 2^(v/32)
;
; No event: REST, the routine returns after the trigger test (output = input, bit for bit).
; A start clears the ring over 16 dry calls (256 words each), then the event runs; its
; envelopes, pitch, spin and gains are set once a call (16 frames), the gains ramped a frame.
; Read: 4-point Hermite, weights once a frame for both taps (half a window apart = whole frames).
;
; X ring: 4096 words, L even / R odd, base a multiple of 4096: the word X:$213 points to (an X address on this effect)
; r7: 00 ST 01 XB 02 WP 03 RNG 04 ARM 05 UH 06 UL 07 DUH 08 DUL 09 PHH 0a PHL 0b NIH 0c NIL 0d SPH 0e AL 0f BL 10 AR 11 BR 12 DAL 13 DBL 14 DAR 15 DBR 16 W0 17 W1 18 W2 19 W3 1a WW1 1b WW2 1c AEN 1d OUTE 1e T1 1f T2 20 HSN 21 RSK

init:
        move    #>$ffffff,m4
        move    r7,r4
        clr     a
        do      #64,>twzero
        move    a,x:(r4)+
twzero:
        nop
        move    x:>$213,r4
        nop
        move    x:(r4),a
        move    a,x:(r7+$01)
        move    a,x:(r7+$02)
        move    #>$00a11c,a
        move    a,x:(r7+$03)
        move    #>$1,a
        move    a,x:(r7+$04)
        rts
proc:
        move    x:(r7+$00),a
        tst     a
        bne     twawake
; ---- REST: the trigger
        move    x:(r6),a
        cmp     #>$400000,a
        bge     twhigh
        move    #>$1,a
        move    a,x:(r7+$04)                 ; under 64: armed
        rts
twhigh:
        move    x:(r7+$04),a
        tst     a
        bne     twstart
        rts
twstart:
; ---- one starts: its length, then 16 clearing calls
        clr     a
        move    a,x:(r7+$04)
        move    a,x:(r7+$05)
        move    a,x:(r7+$06)
        move    a,x:(r7+$09)
        move    a,x:(r7+$0a)
        move    a,x:(r7+$0f)
        move    a,x:(r7+$11)
        move    #>$400000,a
        move    a,x:(r7+$0e)
        move    a,x:(r7+$10)
        move    x:(r7+$01),a
        move    a,x:(r7+$02)
        move    x:(r6+$3),a
        tst     a
        bne     twfixed
        bsr     twrand                  ; RND: 2^-r
        asr     #$5,a,a
        move    a1,a
        bsr     twexp
        move    b,x0
        move    #>$130594,y0
        bra     twlen
twfixed:
        asr     #$3,a,a                 ; (v/32)/32
        move    a1,a
        bsr     twexp
        move    b,x0
        move    #>$5f1be3,y0
twlen:
        mpy     y0,x0,a
        asr     #$c,a,a           ; progress a call, 48 bits
        move    a1,x:(r7+$07)
        move    a0,x:(r7+$08)
        move    x:(r6+$1),a             ; RISE starts where the knob is (glided from here on)
        move    a,x:(r7+$21)
        move    #>$000010,a
        move    a,x:(r7+$00)
        rts
twawake:
        blt     twrun
; ---- clearing: call n (16 .. 1) clears words (n - 1) * 256 ..
        sub     #>$1,a
        move    a,x:(r7+$00)
        asl     #$8,a,a
        move    x:(r7+$01),x0
        add     x0,a
        move    a1,r4
        move    #>$ffffff,m4
        clr     b
        do      #>$000100,>twclr
        move    b,x:(r4)+
twclr:
        nop
        move    x:(r7+$00),a
        tst     a
        bne     twkeep
        move    #>$ffffff,a             ; cleared: RUN from the next call
        move    a,x:(r7+$00)
twkeep:
        rts
twrun:
; ======== the event, once a call ========
        move    x:(r7+$05),a
        move    x:(r7+$06),a0
        move    x:(r7+$07),x1
        move    x:(r7+$08),x0
        add     x,a
        move    #>$7fffff,x0
        cmp     x0,a
        blt     twon
        clr     a                       ; over: REST (the last call's gains were dry within the ramp's LSBs)
        move    a,x:(r7+$00)
        rts
twon:
        move    a1,x:(r7+$05)
        move    a0,x:(r7+$06)
; out = smoothstep((1 - u)/0.15), amount = min(smoothstep(u/0.12), out)
        move    #>$7fffff,a
        move    x:(r7+$05),x0
        sub     x0,a
        move    a,x0
        move    #>$6aaaab,y0
        mpy     y0,x0,a
        asl     #$3,a,a
        move    a,x0
        mpy     x0,x0,a
        move    a,x1                    ; x^2
        move    #>$600000,a
        move    #>$400000,y0
        mac     -y0,x0,a                ; 0.75 - x/2
        move    a,y0
        mpy     x1,y0,a
        asl     #$2,a,a                 ; x^2 (3 - 2x); the move that takes it limits at 1
        move    a,x0
        move    x0,x:(r7+$1d)
        move    x:(r7+$05),x0
        move    #>$42aaab,y0
        mpy     y0,x0,a
        asl     #$4,a,a
        move    a,x0
        mpy     x0,x0,a
        move    a,x1                    ; x^2
        move    #>$600000,a
        move    #>$400000,y0
        mac     -y0,x0,a                ; 0.75 - x/2
        move    a,y0
        mpy     x1,y0,a
        asl     #$2,a,a                 ; x^2 (3 - 2x); the move that takes it limits at 1
        move    x:(r7+$1d),x0
        cmp     x0,a
        tgt     x0,a
        move    a,x:(r7+$1c)
; pitch: semitones = RISE x u^1.3 x out (u^1.3 as a cubic); ratio = 2^(semis/12)
        move    x:(r7+$05),x0
        move    #>$da88f6,y0
        mpy     y0,x0,a
        add     #>$681688,a
        move    a,y0
        mpy     y0,x0,a
        add     #>$3cc747,a
        move    a,y0
        mpy     y0,x0,a                 ; u^1.3
        move    a,x0
        move    x:(r7+$1d),y0
        mpy     y0,x0,a
        move    a,x0
        move    x:(r6+$1),a             ; RISE glided 1/16 a call (5.8 ms): a jumped knob slides, it does not step
        move    x:(r7+$21),b
        sub     b,a
        asr     #$4,a,a
        add     a,b
        move    b,x:(r7+$21)
        move    b,y0
        mpy     y0,x0,a                 ; x RISE/128
        move    a,x0
        move    #>$555555,y0
        mpy     y0,x0,a
        asl     #$4,a,a                 ; E = semis/12, 0..1
        move    a,x0
        move    #>$7fffff,a
        sub     x0,a
        asr     #$5,a,a                 ; (1 - E)/32
        move    a1,a
        bsr     twexp
        asl     b
        sub     #>$7fffff,b             ; ratio - 1
        move    #>$0,x0
        tst     b
        tmi     x0,b
        move    b,x0
        move    #>$408102,y0
        mpy     y0,x0,a
        asr     #$a,a,a
        neg     a                       ; the phase falls by (ratio - 1)/window a frame
        move    a1,x:(r7+$0b)
        move    a0,x:(r7+$0c)
; spin: the angle (as a fraction of pi) moves 0.3 + SPIN u^2 out Hz
        move    x:(r7+$05),x0
        mpy     x0,x0,a
        move    a,x0
        move    x:(r7+$1d),y0
        mpy     y0,x0,a
        move    a,x0
        move    x:(r6+$2),y0
        mpy     y0,x0,a
        move    a,x0
        move    #>$00edc6,y0
        mpy     y0,x0,a
        add     #>$000722,a
        move    x:(r7+$0d),b
        add     b,a
        move    a1,x:(r7+$0d)                ; wraps at +-pi
        move    a1,b                    ; sin: fold to +-pi/2
        abs     b
        move    #>$400000,x0
        cmp     x0,b
        ble     twfold
        neg     b
        add     #>$7fffff,b
twfold:
        asl     b
        move    b,x0
        bsr     twsin                   ; a = 0.5 sin(|angle|)
        move    x:(r7+$0d),b
        tst     b
        bge     twsgn
        neg     a
twsgn:
        move    a,x:(r7+$20)
; gains: g/2 = (0.5 + 0.15 a)(1 - 0.8 a (0.5 +- 0.5 s)); out = 2 (A dry + B wet), A = g/2 (1 - a), B = g/2 a
        move    x:(r7+$1c),x0
        move    #>$133333,y0
        mpy     y0,x0,a
        add     #>$400000,a
        move    a,x:(r7+$1e)                  ; up/2
        move    #>$666666,y0
        mpy     y0,x0,a
        move    a,x:(r7+$1f)                  ; 0.8 a
; left
        move    x:(r7+$20),a
        add     #>$400000,a
        move    a,x0
        move    x:(r7+$1f),y0
        mpy     y0,x0,a
        neg     a
        add     #>$7fffff,a
        move    a,x0
        move    x:(r7+$1e),y0
        mpy     y0,x0,a
        move    a,y0                    ; g/2
        move    x:(r7+$1c),x1
        mpy     x1,y0,a
        move    x:(r7+$0f),b
        sub     b,a
        asr     #$4,a,a
        move    a,x:(r7+$13)
        move    #>$7fffff,a
        sub     x1,a
        move    a,x0
        mpy     y0,x0,a
        move    x:(r7+$0e),b
        sub     b,a
        asr     #$4,a,a
        move    a,x:(r7+$12)
; right
        move    #>$400000,a
        move    x:(r7+$20),x0
        sub     x0,a
        move    a,x0
        move    x:(r7+$1f),y0
        mpy     y0,x0,a
        neg     a
        add     #>$7fffff,a
        move    a,x0
        move    x:(r7+$1e),y0
        mpy     y0,x0,a
        move    a,y0
        mpy     x1,y0,a
        move    x:(r7+$11),b
        sub     b,a
        asr     #$4,a,a
        move    a,x:(r7+$15)
        move    #>$7fffff,a
        sub     x1,a
        move    a,x0
        mpy     y0,x0,a
        move    x:(r7+$10),b
        sub     b,a
        asr     #$4,a,a
        move    a,x:(r7+$14)
; ======== the frames ========
        move    #>$000fff,m1
        move    #>$000fff,m3
        move    x:(r7+$02),r1
        move    #>$1,n0
        do      n7,>twframes
        move    x:(r0),a
        move    a,x:(r1)+
        move    x:(r0+n0),a
        move    a,x:(r1)+
; phase -= (ratio - 1)/window, wrapped 0..1 (48 bits)
        move    x:(r7+$09),a
        move    x:(r7+$0a),a0
        move    x:(r7+$0b),x1
        move    x:(r7+$0c),x0
        add     x,a
        and     #>$7fffff,a
        move    a1,x:(r7+$09)
        move    a0,x:(r7+$0a)
; the Hann pair: tap 1 x sin^2(pi phase), tap 2 x the rest
        move    a1,b
        sub     #>$400000,b
        abs     b
        asl     #$2,b,b
        neg     b
        add     #>$7fffff,b
        move    b,x0                    ; 1 - |4 phase - 2|
        mpy     x0,x0,b
        move    b,x1                    ; u^2
        move    #>$04a277,y0
        mpy     x1,y0,b
        add     #>$d6de19,b
        move    b,y0
        mpy     x1,y0,b
        add     #>$648200,b
        move    b,y0
        mpy     y0,x0,b                 ; 0.5 sin(pi u / 2)
        add     #>$400000,b
        move    b,x0
        move    x0,x:(r7+$1a)
        move    #>$7fffff,b
        sub     x0,b
        move    b,x:(r7+$1b)
; tap 1 sits phase x window frames back (+ 2): whole frames to n, the fraction to the weights
        move    x:(r7+$09),x0
        move    #>$0007f0,y0
        mpy     y0,x0,a
        move    a1,x1                   ; whole frames
        move    a0,b
        not     b
        lsr     b
        move    b1,x0                   ; t = 1 - fraction
; Hermite weights: W0 = t2 - (t3 + t)/2, W2 = 2 t2 + (t - 3 t3)/2, W3 = (t3 - t2)/2, W1 = 1 - the rest
        mpy     x0,x0,a
        move    a,y1                    ; t2
        mpy     x0,y1,b
        move    b,y0                    ; t3
        sub     y1,b
        asr     b
        move    b,x:(r7+$19)
        move    b,a
        move    y0,b
        add     x0,b
        asr     b
        neg     b
        add     y1,b
        move    b,x:(r7+$16)
        add     b,a
        move    y0,b
        asl     b
        add     y0,b
        neg     b
        add     x0,b
        asr     b
        add     y1,b
        add     y1,b
        move    b,x:(r7+$18)
        add     b,a
        move    #>$7fffff,b
        sub     a,b
        move    b,x:(r7+$17)
; tap 1
        move    x1,a
        add     #>$000005,a
        move    a1,n1
        move    a1,n3
        lua     (r1)-n1,r3
        lua     (r3)-n3,r3
        clr     a
        clr     b
        move    x:(r7+$16),y0
        move    x:(r3)+,x0
        mac     y0,x0,a
        move    x:(r3)+,x0
        mac     y0,x0,b
        move    x:(r7+$17),y0
        move    x:(r3)+,x0
        mac     y0,x0,a
        move    x:(r3)+,x0
        mac     y0,x0,b
        move    x:(r7+$18),y0
        move    x:(r3)+,x0
        mac     y0,x0,a
        move    x:(r3)+,x0
        mac     y0,x0,b
        move    x:(r7+$19),y0
        move    x:(r3)+,x0
        mac     y0,x0,a
        move    x:(r3)+,x0
        mac     y0,x0,b
        move    a,x:(r7+$1e)
        move    b,x:(r7+$1f)
; tap 2: half a window further round
        move    x1,b
        add     #>$0003f8,b
        move    b,y1
        sub     #>$0007f0,b
        tmi     y1,b
        add     #>$000005,b
        move    b1,n1
        move    b1,n3
        lua     (r1)-n1,r3
        lua     (r3)-n3,r3
        clr     a
        clr     b
        move    x:(r7+$16),y0
        move    x:(r3)+,x0
        mac     y0,x0,a
        move    x:(r3)+,x0
        mac     y0,x0,b
        move    x:(r7+$17),y0
        move    x:(r3)+,x0
        mac     y0,x0,a
        move    x:(r3)+,x0
        mac     y0,x0,b
        move    x:(r7+$18),y0
        move    x:(r3)+,x0
        mac     y0,x0,a
        move    x:(r3)+,x0
        mac     y0,x0,b
        move    x:(r7+$19),y0
        move    x:(r3)+,x0
        mac     y0,x0,a
        move    x:(r3)+,x0
        mac     y0,x0,b
        move    x:(r7+$1e),x1
        move    x:(r7+$1f),y1
        move    x:(r7+$1a),y0
        move    a,x0
        mpy     x1,y0,a
        move    x:(r7+$1b),x1
        mac     x1,x0,a
        move    b,x0
        mpy     y1,y0,b
        mac     x1,x0,b
        move    a,x1                    ; wet L
        move    b,y1                    ; wet R
; left: 2 (A dry + B wet), A and B ramped to this call's values
        move    x:(r7+$0e),b
        move    x:(r7+$12),y0
        add     y0,b
        move    b,x:(r7+$0e)
        move    b,y0
        move    x:(r0),x0
        mpy     y0,x0,a
        move    x:(r7+$0f),b
        move    x:(r7+$13),y0
        add     y0,b
        move    b,x:(r7+$0f)
        move    b,y0
        mac     x1,y0,a
        asl     a
        move    a,x:(r0)+
; right
        move    x:(r7+$10),b
        move    x:(r7+$14),y0
        add     y0,b
        move    b,x:(r7+$10)
        move    b,y0
        move    x:(r0),x0
        mpy     y0,x0,a
        move    x:(r7+$11),b
        move    x:(r7+$15),x0
        add     x0,b
        move    b,x:(r7+$11)
        move    b,x0
        mac     x0,y1,a
        asl     a
        move    a,x:(r0)+
twframes:
        nop
        move    r1,x:(r7+$02)
        move    #>$ffffff,m1
        move    #>$ffffff,m3
        rts
; ---- subroutines (after their callers) ----
twrand:
        move    x:(r7+$03),x0
        move    #>$0343fd,y0
        mpy     y0,x0,a
        asr     a                       ; a1:a0 = the whole product, a0 its low 24 bits
        move    a0,x0
        move    x0,a
        add     #>$269ec3,a
        move    a1,x:(r7+$03)
        move    a1,b
        lsr     b
        move    b1,x0
        move    x0,a
        rts
twexp:
        move    a1,b
        asr     #$12,a,a  ; a1 = n = floor(y)
        add     #>$1,a
        move    a1,x1  ; n + 1 (never 0: a do count of 0 is not a skip)
        and     #>$03ffff,b
        asl     #$5,b,b  ; f in Q23, b2 stays 0
        move    b1,x0
        move    #>$2c5c86,y0
        mpy     y0,x0,b
        move    b,y0  ; g = f ln2 / 2
        move    #>$02aaab,x0
        mpy     y0,x0,b
        sub     #>$0aaaab,b
        move    b,x0
        mpy     y0,x0,b
        add     #>$200000,b
        move    b,x0
        mpy     y0,x0,b
        sub     #>$400000,b
        move    b,x0
        mpy     y0,x0,b
        add     #>$400000,b  ; e^-g / 2
        move    b,x0
        mpy     x0,x0,b
        asl     #$2,b,b  ; 2^-f in (0.5, 1]
        do      x1,>twpow
        asr     b
twpow:
        asl     b
        rts
twsin:
        mpy     x0,x0,a
        move    a,x1                    ; u^2
        move    #>$04a277,y0
        mpy     x1,y0,a
        add     #>$d6de19,a
        move    a,y0
        mpy     x1,y0,a
        add     #>$648200,a
        move    a,y0
        mpy     y0,x0,a                 ; 0.5 sin(pi u / 2)
        rts
